/**
 * _ma-12.mjs — mã THẬT của dự án cuối khoá dbg-cap (sinh bởi scratchpad/dbg/lab/ch12/tools/sinh.mjs, 24/11/2026). Đã escape HTML.
 */
export const CHAY = "#!/bin/bash\n# chay.sh — dựng lại TOÀN BỘ dbg-cap từ đầu: PostgreSQL 16 (docker), lich-api (Spring Boot), dat-api (Node), web (React + Vite).\n#   ./chay.sh          # nạp lại CSDL mẫu (mất dữ liệu cũ!), build Java, chạy 3 dịch vụ ở nền\n#   ./dung.sh          # dừng 3 dịch vụ (giữ container CSDL)\n# Cổng (chỉ bind 127.0.0.1/localhost): web 41200 · lich-api 41201 (JDWP 45005) · dat-api 41202 (inspector 41209) · PostgreSQL 45432\nset -euo pipefail\ncd \"$(dirname \"$0\")\"; G=$PWD; mkdir -p .chay\nDB=${DB_NAME:-labflow_cap}\nbash dung.sh 2&gt;/dev/null || true\n\n# 1. PostgreSQL — pg_stat_statements để đếm câu SQL, log_lock_waits + deadlock_timeout 1 s để thấy khoá trong log\nif ! docker ps --format '{{.Names}}' | grep -qx dbg-pg; then\n  docker rm -f dbg-pg &gt;/dev/null 2&gt;&amp;1 || true\n  docker run -d --name dbg-pg -e POSTGRES_PASSWORD=dbg -p 127.0.0.1:45432:5432 postgres:16 \\\n    -c shared_preload_libraries=pg_stat_statements -c log_lock_waits=on -c deadlock_timeout=1s &gt;/dev/null\n  until docker exec dbg-pg pg_isready -U postgres -q; do sleep 1; done; sleep 2\nfi\npsql_() { docker exec -i dbg-pg psql -U postgres -v ON_ERROR_STOP=1 -q \"$@\"; }\npsql_ -c \"DROP DATABASE IF EXISTS $DB WITH (FORCE)\" -c \"CREATE DATABASE $DB\"\nfor f in db/schema.sql db/seed.sql $(ls db/sua-*.sql 2&gt;/dev/null); do psql_ -d $DB &lt; $f; done\necho \"CSDL $DB: $(psql_ -d $DB -tAc 'select count(*) from dat_cho') lượt đặt, $(psql_ -d $DB -tAc 'select count(*) from phong') phòng\"\n\n# 2. lich-api — build bằng Maven, chạy kèm JDWP để IntelliJ \"Attach to process\" / Remote JVM Debug vào 45005\n(cd java &amp;&amp; mvn -q -DskipTests package dependency:copy-dependencies -DincludeScope=runtime -DoutputDirectory=target/lib)\n(cd java &amp;&amp; DB_NAME=$DB GIT_COMMIT=$(git -C \"$G/node\" rev-parse --short HEAD 2&gt;/dev/null || echo dev) \\\n  exec java -agentlib:jdwp=transport=dt_socket,server=y,suspend=n,address=127.0.0.1:45005 \\\n  -cp 'target/classes:target/lib/*' vn.labflow.cap.CapApp &gt; \"$G/.chay/lich-api.log\" 2&gt;&amp;1) &amp;\necho $! &gt; .chay/lich-api.pid\n\n# 3. dat-api — Node 22, inspector mở sẵn ở 127.0.0.1:41209 (chrome://inspect hoặc VS Code \"Attach\")\n(cd node &amp;&amp; [ -d node_modules ] || npm ci --silent)\n(cd node &amp;&amp; DATABASE_URL=postgresql://postgres:dbg@127.0.0.1:45432/$DB GIT_COMMIT=$(git rev-parse --short HEAD 2&gt;/dev/null || echo dev) \\\n  exec node --inspect=127.0.0.1:41209 src/app.mjs &gt; \"$G/.chay/dat-api.log\" 2&gt;&amp;1) &amp;\necho $! &gt; .chay/dat-api.pid\n\n# 4. web\n(cd web &amp;&amp; [ -d node_modules ] || npm ci --silent)\n(cd web &amp;&amp; exec node_modules/.bin/vite &gt; \"$G/.chay/web.log\" 2&gt;&amp;1) &amp;\necho $! &gt; .chay/web.pid\n\nfor i in $(seq 90); do curl -sf -o /dev/null 127.0.0.1:41201/api/health &amp;&amp; curl -sf -o /dev/null 127.0.0.1:41202/health &amp;&amp; curl -sf -o /dev/null localhost:41200 &amp;&amp; break; sleep 1; done\necho \"lich-api: $(curl -s 127.0.0.1:41201/api/health)\"\necho \"dat-api : $(curl -s 127.0.0.1:41202/health)\"\necho \"web     : http://localhost:41200     log: .chay/*.log     kiểm: (cd kiem &amp;&amp; npm ci --silent); node kiem/kiem.mjs\"";
export const SCHEMA = "-- schema.sql — CSDL của dự án cuối khoá dbg-cap (LabFlow: đặt lịch phòng lab). PostgreSQL 16.\n-- Chạy: psql -v ON_ERROR_STOP=1 -f db/schema.sql -f db/seed.sql   (chay.sh làm việc này)\nCREATE EXTENSION IF NOT EXISTS pg_stat_statements;\n\nCREATE TABLE nguoi_dung (\n  id    serial PRIMARY KEY,\n  ten   text NOT NULL,\n  email text NOT NULL UNIQUE\n);\n\nCREATE TABLE phong (\n  id         serial PRIMARY KEY,\n  ten        text NOT NULL,\n  suc_chua   int  NOT NULL,\n  quan_ly_id int  REFERENCES nguoi_dung(id)          -- phòng mới mở có thể chưa có người quản lý\n);\n\nCREATE TABLE dat_cho (\n  id         serial PRIMARY KEY,\n  phong_id   int  NOT NULL REFERENCES phong(id),\n  nguoi_id   int  NOT NULL REFERENCES nguoi_dung(id),\n  bat_dau    timestamptz NOT NULL,\n  ket_thuc   timestamptz NOT NULL,\n  trang_thai text NOT NULL DEFAULT 'xac_nhan',        -- xac_nhan | huy\n  tao_luc    timestamptz NOT NULL DEFAULT now(),\n  CHECK (ket_thuc &gt; bat_dau)\n);\nCREATE INDEX dat_cho_phong ON dat_cho (phong_id, bat_dau);\nCREATE INDEX dat_cho_nguoi ON dat_cho (nguoi_id, bat_dau DESC);";
export const SEED = "-- seed.sql — dữ liệu mẫu TẤT ĐỊNH (chạy lại ra đúng các id như nhau). Giờ ghi theo giờ Việt Nam (+07).\n-- 30 sinh viên + 1 tài khoản của bộ kiểm; 24 phòng (phòng 7 và 19 chưa có người quản lý);\n-- lịch từ 16/11 tới 14/12/2026, 6 ca mỗi ngày; ca sớm 06:30–07:30 (= 23:30 UTC hôm TRƯỚC).\nINSERT INTO nguoi_dung (ten, email)\nSELECT 'Sinh viên ' || lpad(i::text, 2, '0'), 'sv' || lpad(i::text, 2, '0') || '@labflow.test' FROM generate_series(1, 30) i;\nINSERT INTO nguoi_dung (ten, email) VALUES ('Bộ kiểm tự động', 'kiem@labflow.test');   -- id 31\n\nINSERT INTO phong (ten, suc_chua, quan_ly_id)\nSELECT 'Lab ' || i, 20 + (i % 3) * 10, CASE WHEN i IN (7, 19) THEN NULL ELSE 1 + (i * 11) % 30 END\nFROM generate_series(1, 24) i;\n\nINSERT INTO dat_cho (phong_id, nguoi_id, bat_dau, ket_thuc, tao_luc)\nSELECT r, 1 + (r * 13 + d * 7 + s * 5) % 30,\n       (date '2026-11-16' + d + ca.bd) AT TIME ZONE 'Asia/Ho_Chi_Minh',\n       (date '2026-11-16' + d + ca.kt) AT TIME ZONE 'Asia/Ho_Chi_Minh',\n       (date '2026-11-16' + d + ca.bd - interval '3 days') AT TIME ZONE 'Asia/Ho_Chi_Minh'\nFROM generate_series(0, 28) d,\n     generate_series(1, 24) r,\n     (VALUES (1, time '06:30', time '07:30'), (2, '07:30', '09:30'), (3, '09:30', '11:30'),\n             (4, '13:00', '15:00'), (5, '15:00', '17:00'), (6, '17:30', '19:30')) AS ca(s, bd, kt)\nWHERE (r * 7 + d * 3 + s * 5) % 4 &lt;&gt; 0\n  AND (s &lt;&gt; 1 OR (r + d) % 3 = 0)          -- ca sớm chỉ một phần phòng có\nORDER BY d, s, r;";
export const KIEM = "// kiem.mjs — bộ kiểm tự động của dự án cuối khoá dbg-cap: mỗi lỗi một phép kiểm, chạy bằng HTTP + SQL như người kiểm thử thật.\n// ĐỎ = lỗi còn đó, XANH = đã sửa. KHÔNG sửa tệp này (bộ chấm dùng bản gốc).\n//   node kiem/kiem.mjs            # cả 10 lỗi\n//   node kiem/kiem.mjs 3 6        # chỉ lỗi 3 và 6\n// Biến môi trường (mặc định là bản chạy bằng ./chay.sh): JAVA, NODE, INSPECT, DB, WEB_ORIGIN\nimport http from 'node:http';\nimport pg from 'pg';\n\nconst JAVA = process.env.JAVA || 'http://127.0.0.1:41201';\nconst NODE = process.env.NODE || 'http://127.0.0.1:41202';\nconst INSPECT = process.env.INSPECT || '127.0.0.1:41209';\nconst DB = process.env.DB || 'postgresql://postgres:dbg@127.0.0.1:45432/labflow_cap';\nconst ORIGIN = process.env.WEB_ORIGIN || 'http://localhost:41200';\nconst KIEM = 31;                                   // nguoi_dung \"Bộ kiểm tự động\"\n\nconst db = new pg.Client({ connectionString: DB });\nconst ngu = (ms) =&gt; new Promise((r) =&gt; setTimeout(r, ms));\nconst goi = async (url, opt = {}) =&gt; {\n  const r = await fetch(url, { ...opt, headers: { 'Content-Type': 'application/json', ...(opt.headers || {}) }, body: opt.body &amp;&amp; JSON.stringify(opt.body) });\n  let body = null; try { body = await r.json(); } catch {}\n  return { status: r.status, body, h: r.headers };\n};\nconst vn = (s) =&gt; `${s}+07:00`;\n\nconst KIEM_LOI = {\n  1: ['NPE thống kê phòng', async () =&gt; {\n    const { rows } = await db.query('SELECT id FROM phong WHERE quan_ly_id IS NULL ORDER BY id');\n    const sai = [];\n    for (const { id } of rows) {\n      const r = await goi(`${JAVA}/api/phong/${id}/thong-ke`);\n      if (r.status !== 200 || r.body?.quanLy !== null) sai.push(`phòng ${id} → ${r.status}`);\n    }\n    return [sai.length === 0, sai.length ? sai.join('; ') : `${rows.length} phòng chưa có quản lý đều trả 200, quanLy = null`];\n  }],\n\n  2: ['Phân trang lịch sử đặt chỗ', async () =&gt; {\n    const { rows } = await db.query('SELECT id FROM dat_cho WHERE nguoi_id = 3 ORDER BY bat_dau DESC, id DESC');\n    const r1 = await goi(`${JAVA}/api/nguoi/3/dat-cho?trang=1&amp;co=10`);\n    const dau = r1.body?.muc?.[0]?.id;\n    const thay = new Set();\n    for (let t = 1; t &lt;= (r1.body?.soTrang || 0); t++) (await goi(`${JAVA}/api/nguoi/3/dat-cho?trang=${t}&amp;co=10`)).body.muc.forEach((d) =&gt; thay.add(d.id));\n    const ok = dau === rows[0].id &amp;&amp; thay.size === rows.length;\n    return [ok, `trang 1 bắt đầu ở #${dau} (mới nhất là #${rows[0].id}); đi hết ${r1.body?.soTrang} trang thấy ${thay.size}/${rows.length} lượt`];\n  }],\n\n  3: ['CORS cho giao diện web', async () =&gt; {\n    const sai = [];\n    for (const [duong, method] of [['/phong', 'GET'], ['/dat-cho', 'POST']]) {\n      const r = await fetch(NODE + duong, { method: 'OPTIONS', headers: { Origin: ORIGIN, 'Access-Control-Request-Method': method, 'Access-Control-Request-Headers': 'content-type,x-request-id' } });\n      const ao = r.headers.get('access-control-allow-origin'); const ah = (r.headers.get('access-control-allow-headers') || '').toLowerCase();\n      const am = (r.headers.get('access-control-allow-methods') || '').toUpperCase();\n      if (ao !== ORIGIN || !/x-request-id/.test(ah) || !/content-type/.test(ah) || !am.includes(method)) sai.push(`${method} ${duong}: Allow-Headers \"${r.headers.get('access-control-allow-headers')}\"`);\n    }\n    return [sai.length === 0, sai.length ? sai.join('; ') : 'preflight cho phép content-type + x-request-id từ ' + ORIGIN];\n  }],\n\n  4: ['Báo cáo ngày theo giờ VN', async () =&gt; {\n    const ngay = '2026-12-01';\n    const { rows } = await db.query(`SELECT id FROM dat_cho WHERE trang_thai &lt;&gt; 'huy' AND (bat_dau AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = $1`, [ngay]);\n    const mong = new Set(rows.map((x) =&gt; x.id));\n    const r = await goi(`${NODE}/bao-cao/ngay?ngay=${ngay}`);\n    const co = new Set(r.body?.ids || []);\n    const thieu = [...mong].filter((x) =&gt; !co.has(x)).length; const thua = [...co].filter((x) =&gt; !mong.has(x)).length;\n    return [thieu === 0 &amp;&amp; thua === 0 &amp;&amp; r.body?.tong === mong.size, `ngày ${ngay}: API ${r.body?.tong} lượt, đúng là ${mong.size}; thiếu ${thieu}, thừa ${thua}`];\n  }],\n\n  5: ['N+1 ở danh sách phòng', async () =&gt; {\n    await goi(`${JAVA}/api/phong`);                                         // làm nóng\n    await db.query('SELECT pg_stat_statements_reset()');\n    const r = await goi(`${JAVA}/api/phong`);\n    await ngu(300);\n    const { rows: [s] } = await db.query(\n      `SELECT coalesce(sum(calls), 0)::int AS n FROM pg_stat_statements\n        WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database()) AND query !~* 'pg_stat_statements'`);\n    return [r.status === 200 &amp;&amp; s.n &lt;= 3, `GET /api/phong (${r.body?.length} phòng) chạy ${s.n} câu SQL`];\n  }],\n\n  6: ['Đặt trùng khi bấm đồng thời', async () =&gt; {\n    const lan = 20, vong = 8, ket = [];               // 8 vòng: một bản sửa \"qua\" một lần chưa chắc đã qua lần sau\n    let ok = true;\n    for (let v = 0; v &lt; vong; v++) {\n      await db.query('DELETE FROM dat_cho WHERE nguoi_id = $1', [KIEM]);\n      // làm nóng như trên prod: mở sẵn kết nối HTTP keep-alive và pool PostgreSQL của dat-api\n      await Promise.all(Array.from({ length: lan }, (_, i) =&gt; goi(i % 2 ? `${NODE}/health` : `${NODE}/bao-cao/ngay?ngay=2027-01-05`)));\n      const kq = await Promise.all(Array.from({ length: lan }, () =&gt; goi(`${NODE}/dat-cho`, { method: 'POST',\n        body: { phongId: 22, nguoiId: KIEM, batDau: vn('2027-01-05T09:00:00'), ketThuc: vn('2027-01-05T10:00:00') } })));\n      const dem = {}; kq.forEach((r) =&gt; (dem[r.status] = (dem[r.status] || 0) + 1));\n      const { rows: [d] } = await db.query(`SELECT count(*)::int AS n FROM dat_cho WHERE phong_id = 22 AND nguoi_id = $1 AND trang_thai &lt;&gt; 'huy'`, [KIEM]);\n      const dung = dem[201] === 1 &amp;&amp; dem[409] === lan - 1 &amp;&amp; d.n === 1;\n      if (!dung) ok = false;\n      ket.push([dung, `${Object.entries(dem).map(([k, n]) =&gt; `${n}×${k}`).join(' ')} → ${d.n} lượt trong CSDL`]);\n    }\n    const sai = ket.filter(([x]) =&gt; !x).map(([, s]) =&gt; s);\n    return [ok, `${vong} vòng × ${lan} request cùng lúc: ${vong - sai.length}/${vong} vòng đúng (1×201, ${lan - 1}×409)${sai.length ? '; vòng sai: ' + [...new Set(sai)].slice(0, 3).join(' | ') : ''}`];\n  }],\n\n  7: ['Đổi giờ song song (deadlock)', async () =&gt; {\n    const ins = (phong, a, b) =&gt; db.query('INSERT INTO dat_cho (phong_id, nguoi_id, bat_dau, ket_thuc) VALUES ($1, $2, $3, $4) RETURNING id', [phong, KIEM, vn(a), vn(b)]);\n    const { rows: [{ id: a }] } = await ins(23, '2027-01-06T09:00:00', '2027-01-06T10:00:00');\n    const { rows: [{ id: b }] } = await ins(24, '2027-01-06T13:00:00', '2027-01-06T15:00:00');\n    const lan = 40;\n    const kq = await Promise.all(Array.from({ length: lan }, (_, i) =&gt; goi(`${JAVA}/api/dat-cho/doi-gio`, { method: 'POST', body: i % 2 ? { a, b } : { a: b, b: a } })));\n    const loi = kq.filter((r) =&gt; r.status !== 200).length;\n    return [loi === 0, `${lan} lượt đổi giờ #${a} ⇄ #${b} cùng lúc: ${lan - loi} thành công, ${loi} lỗi${loi ? ' (' + [...new Set(kq.filter((r) =&gt; r.status !== 200).map((r) =&gt; r.status))].join('/') + ')' : ''}`];\n  }],\n\n  8: ['Rò rỉ khi đóng kết nối sự kiện', async () =&gt; {\n    const t = (await (await fetch(`http://${INSPECT}/json/list`)).json())[0];\n    const ws = new WebSocket(t.webSocketDebuggerUrl); await new Promise((r, j) =&gt; { ws.onopen = r; ws.onerror = j; });\n    let id = 0; const cho = new Map(); ws.onmessage = (e) =&gt; { const m = JSON.parse(e.data); cho.get(m.id)?.(m); };\n    const gui = (method, params = {}) =&gt; new Promise((r) =&gt; { const i = ++id; cho.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });\n    const doc = async () =&gt; {\n      await gui('HeapProfiler.collectGarbage');\n      const r = await gui('Runtime.evaluate', { expression: `JSON.stringify({ hen: process.getActiveResourcesInfo().filter((x) =&gt; x === 'Timeout').length, heap: process.memoryUsage().heapUsed })`, returnByValue: true });\n      return JSON.parse(r.result.result.value);\n    };\n    const truoc = await doc();\n    const lan = 300;\n    for (let i = 0; i &lt; lan; i += 50) {\n      await Promise.all(Array.from({ length: 50 }, () =&gt; new Promise((xong) =&gt; {\n        const rq = http.get(`${NODE}/su-kien`, (res) =&gt; res.once('data', () =&gt; { rq.destroy(); xong(); }));\n        rq.on('error', xong);\n      })));\n    }\n    await ngu(500);\n    const sau = await doc(); ws.close();\n    const tang = sau.hen - truoc.hen;\n    return [tang &lt; 5, `mở rồi đóng ${lan} kết nối /su-kien: bộ hẹn giờ còn sống ${truoc.hen} → ${sau.hen}, heap ${(truoc.heap / 2 ** 20).toFixed(1)} → ${(sau.heap / 2 ** 20).toFixed(1)} MB`];\n  }],\n\n  9: ['Tên phòng cũ sau khi đổi', async () =&gt; {\n    const id = 21;\n    const cu = (await goi(`${NODE}/phong/${id}`)).body?.ten;            // trang Phòng vừa được xem ⇒ đã vào đệm\n    const moi = `Lab ${id} (kiểm ${Date.now() % 100000})`;\n    const p = await goi(`${JAVA}/api/phong/${id}`, { method: 'PUT', body: { ten: moi } });\n    await ngu(1500);\n    const r = await goi(`${NODE}/phong/${id}`);\n    await goi(`${JAVA}/api/phong/${id}`, { method: 'PUT', body: { ten: `Lab ${id}` } });\n    return [p.status === 200 &amp;&amp; r.body?.ten === moi, `đổi \"${cu}\" → \"${moi}\" ở lich-api; 1,5 s sau dat-api trả \"${r.body?.ten}\" (X-Cache: ${r.h.get('x-cache')})`];\n  }],\n\n  10: ['Đặt ca liền kề', async () =&gt; {\n    const dat = (a, b) =&gt; goi(`${NODE}/dat-cho`, { method: 'POST', body: { phongId: 20, nguoiId: KIEM, batDau: vn(a), ketThuc: vn(b) } });\n    const r1 = await dat('2027-01-07T10:00:00', '2027-01-07T11:00:00');\n    const r2 = await dat('2027-01-07T11:00:00', '2027-01-07T12:00:00');\n    return [r1.status === 201 &amp;&amp; r2.status === 201, `10:00–11:00 → ${r1.status}; 11:00–12:00 → ${r2.status}${r2.body?.loi ? ' \"' + r2.body.loi + '\"' : ''}`];\n  }],\n};\n\nawait db.connect();\nconst don = () =&gt; db.query('DELETE FROM dat_cho WHERE nguoi_id = $1', [KIEM]);\nconst chon = process.argv.slice(2).map(Number).filter(Boolean);\nconsole.log(`Bộ kiểm dbg-cap · lich-api ${JAVA} · dat-api ${NODE} · CSDL ${DB.split('/').pop()}`);\nlet xanh = 0; const so = chon.length ? chon : Object.keys(KIEM_LOI).map(Number);\nfor (const n of so) {\n  const [ten, ham] = KIEM_LOI[n];\n  await don();\n  let ok, chiTiet;\n  try { [ok, chiTiet] = await ham(); } catch (e) { ok = false; chiTiet = `không chạy được: ${e.cause?.code || e.message}`; }\n  if (ok) xanh++;\n  console.log(`#${String(n).padEnd(2)} ${ten.padEnd(32)} ${ok ? 'XANH' : 'ĐỎ  '}  ${chiTiet}`);\n}\nawait don(); await db.end();\nconsole.log(`Kết quả: ${xanh}/${so.length} xanh`);\nprocess.exitCode = so.length - xanh;";
export const API_JS = "// api.js — gọi hai dịch vụ. Mỗi request gắn X-Request-Id để tra log hai phía (Chương 6).\nconst LICH = import.meta.env.LICH_API;\nconst DAT = import.meta.env.DAT_API;\n\nasync function goi(url, opt = {}) {\n  const r = await fetch(url, { ...opt, headers: { 'X-Request-Id': crypto.randomUUID(), ...(opt.headers || {}) } });\n  const body = await r.json().catch(() =&gt; ({}));\n  if (!r.ok) throw Object.assign(new Error(body.loi || body.error || `HTTP ${r.status}`), { status: r.status });\n  return body;\n}\n\nexport const api = {\n  phong: () =&gt; goi(`${DAT}/phong`),\n  thongKe: (id) =&gt; goi(`${LICH}/api/phong/${id}/thong-ke`),\n  lichSu: (nguoi, trang) =&gt; goi(`${LICH}/api/nguoi/${nguoi}/dat-cho?trang=${trang}&amp;co=10`),\n  baoCao: (ngay) =&gt; goi(`${DAT}/bao-cao/ngay?ngay=${ngay}`),\n  datCho: (d) =&gt; goi(`${DAT}/dat-cho`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(d) }),\n  suKien: () =&gt; new EventSource(`${DAT}/su-kien`),\n};";
export const APP_NODE = "// app.mjs — dat-api: đặt chỗ, báo cáo ngày, danh sách phòng (đệm từ lich-api), sự kiện trực tiếp. Cổng 41202.\nimport http from 'node:http';\nimport { randomUUID } from 'node:crypto';\nimport { cors } from './cors.mjs';\nimport { datCho } from './dat-cho.mjs';\nimport { baoCaoNgay } from './bao-cao.mjs';\nimport { layHoacTai } from './cache.mjs';\nimport { moSuKien, phat } from './su-kien.mjs';\n\nconst PORT = Number(process.env.PORT || 41202);\nconst LICH_API = process.env.LICH_API || 'http://127.0.0.1:41201';\nconst PHIEN_BAN = '1.6.0';\n\nconst json = (res, code, body, them = {}) =&gt; { res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8', ...them }); res.end(JSON.stringify(body)); };\nconst docBody = async (req) =&gt; { let b = ''; for await (const ch of req) b += ch; return b ? JSON.parse(b) : {}; };\n\nasync function layPhong() {\n  const r = await fetch(`${LICH_API}/api/phong`);\n  if (!r.ok) throw new Error(`lich-api trả ${r.status}`);\n  return r.json();\n}\n\nhttp.createServer(async (req, res) =&gt; {\n  const rid = req.headers['x-request-id'] || randomUUID();\n  const t0 = performance.now();\n  res.setHeader('X-Request-Id', rid);\n  res.on('finish', () =&gt; console.log(JSON.stringify({ rid, m: req.method, u: req.url, s: res.statusCode, ms: +(performance.now() - t0).toFixed(1) })));\n  if (cors(req, res)) return;\n  const url = new URL(req.url, 'http://x');\n  try {\n    if (url.pathname === '/health') return json(res, 200, { dichVu: 'dat-api', phienBan: PHIEN_BAN, commit: process.env.GIT_COMMIT || 'dev', node: process.version });\n    if (url.pathname === '/su-kien') return moSuKien(req, res);\n    if (req.method === 'GET' &amp;&amp; url.pathname === '/phong') {\n      const { giaTri, trung, tuoi } = await layHoacTai('phong', layPhong);\n      return json(res, 200, giaTri, { 'X-Cache': trung ? `HIT; age=${tuoi}` : 'MISS' });\n    }\n    const m = url.pathname.match(/^\\/phong\\/(\\d+)$/);\n    if (req.method === 'GET' &amp;&amp; m) {\n      const { giaTri, trung, tuoi } = await layHoacTai('phong', layPhong);\n      const p = giaTri.find((x) =&gt; x.id === Number(m[1]));\n      return p ? json(res, 200, p, { 'X-Cache': trung ? `HIT; age=${tuoi}` : 'MISS' }) : json(res, 404, { loi: 'Không có phòng' });\n    }\n    if (req.method === 'POST' &amp;&amp; url.pathname === '/dat-cho') {\n      const kq = await datCho(await docBody(req));\n      if (kq.code === 201) phat('dat-cho', kq.body);\n      return json(res, kq.code, kq.body);\n    }\n    if (req.method === 'GET' &amp;&amp; url.pathname === '/bao-cao/ngay') {\n      const kq = await baoCaoNgay(url.searchParams.get('ngay'));\n      return json(res, kq.code, kq.body);\n    }\n    json(res, 404, { loi: 'Không có đường này' });\n  } catch (e) {\n    console.error(JSON.stringify({ rid, loi: e.message, code: e.code, stack: e.stack.split('\\n').slice(0, 4).join(' | ') }));\n    json(res, 500, { loi: 'Lỗi máy chủ', rid });\n  }\n}).listen(PORT, '127.0.0.1', () =&gt; console.log(`dat-api ${PHIEN_BAN} :${PORT} pid ${process.pid}`));";
export const PHONG_SV = "package vn.labflow.cap;\n\nimport java.time.OffsetDateTime;\nimport java.util.List;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport org.springframework.web.server.ResponseStatusException;\nimport vn.labflow.cap.Dto.*;\n\n@Service\npublic class PhongService {\n  private final PhongRepo phongRepo;\n  private final DatChoRepo datChoRepo;\n\n  PhongService(PhongRepo phongRepo, DatChoRepo datChoRepo) { this.phongRepo = phongRepo; this.datChoRepo = datChoRepo; }\n\n  /** Trang \"Phòng\": mọi phòng + số lịch sắp tới. */\n  @Transactional(readOnly = true)\n  public List&lt;PhongTomTat&gt; danhSach() {\n    OffsetDateTime bayGio = OffsetDateTime.now();\n    return phongRepo.findAll().stream()\n        .sorted((x, y) -&gt; x.getId() - y.getId())\n        .map(p -&gt; new PhongTomTat(p.getId(), p.getTen(), p.getSucChua(),\n            p.getQuanLy() == null ? null : p.getQuanLy().getTen(),\n            p.getDatCho().stream().filter(d -&gt; !\"huy\".equals(d.getTrangThai()) &amp;&amp; d.getBatDau().isAfter(bayGio)).count()))\n        .toList();\n  }\n\n  /** Trang chi tiết phòng. */\n  @Transactional(readOnly = true)\n  public ThongKePhong thongKe(Integer id) {\n    Phong p = phongRepo.findById(id).orElseThrow(() -&gt; new ResponseStatusException(HttpStatus.NOT_FOUND, \"Không có phòng \" + id));\n    return new ThongKePhong(p.getId(), p.getTen(), p.getQuanLy().getTen(), datChoRepo.demTheoPhong(id));\n  }\n\n  @Transactional\n  public ThongKePhong doiTen(Integer id, String ten) {\n    Phong p = phongRepo.findById(id).orElseThrow(() -&gt; new ResponseStatusException(HttpStatus.NOT_FOUND, \"Không có phòng \" + id));\n    p.setTen(ten);\n    return new ThongKePhong(p.getId(), p.getTen(), p.getQuanLy() == null ? null : p.getQuanLy().getTen(), datChoRepo.demTheoPhong(id));\n  }\n}";
export const DATCHO_SV = "package vn.labflow.cap;\n\nimport org.springframework.data.domain.Page;\nimport org.springframework.data.domain.PageRequest;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport org.springframework.web.server.ResponseStatusException;\nimport vn.labflow.cap.Dto.*;\n\n@Service\npublic class DatChoService {\n  private final DatChoRepo repo;\n\n  DatChoService(DatChoRepo repo) { this.repo = repo; }\n\n  /** Lịch sử đặt chỗ của một người, mới nhất trước. trang đánh số từ 1 (như trên giao diện). */\n  @Transactional(readOnly = true)\n  public TrangDatCho lichSu(Integer nguoiId, int trang, int co) {\n    Page&lt;DatCho&gt; p = repo.findByNguoiIdOrderByBatDauDescIdDesc(nguoiId, PageRequest.of(trang, co));\n    return new TrangDatCho(trang, co, p.getTotalElements(), p.getTotalPages(),\n        p.getContent().stream().map(d -&gt; new DatChoGon(d.getId(), d.getPhong().getId(), d.getBatDau(), d.getKetThuc(), d.getTrangThai())).toList());\n  }\n\n  /** Hai bạn đổi khung giờ cho nhau (mỗi bạn giữ phòng của mình). */\n  @Transactional\n  public void doiGio(Integer a, Integer b) {\n    DatCho x = repo.khoaDeSua(a).orElseThrow(() -&gt; khongCo(a));\n    if (\"huy\".equals(x.getTrangThai())) throw new ResponseStatusException(HttpStatus.CONFLICT, \"Lịch \" + a + \" đã huỷ\");\n    DatCho y = repo.khoaDeSua(b).orElseThrow(() -&gt; khongCo(b));\n    if (\"huy\".equals(y.getTrangThai())) throw new ResponseStatusException(HttpStatus.CONFLICT, \"Lịch \" + b + \" đã huỷ\");\n    var bd = x.getBatDau(); var kt = x.getKetThuc();\n    x.doiGio(y.getBatDau(), y.getKetThuc());\n    y.doiGio(bd, kt);\n  }\n\n  private static ResponseStatusException khongCo(Integer id) { return new ResponseStatusException(HttpStatus.NOT_FOUND, \"Không có lịch \" + id); }\n}";
export const DATCHO_REPO = "package vn.labflow.cap;\n\nimport jakarta.persistence.LockModeType;\nimport java.util.Optional;\nimport org.springframework.data.domain.Page;\nimport org.springframework.data.domain.Pageable;\nimport org.springframework.data.jpa.repository.JpaRepository;\nimport org.springframework.data.jpa.repository.Lock;\nimport org.springframework.data.jpa.repository.Query;\n\npublic interface DatChoRepo extends JpaRepository&lt;DatCho, Integer&gt; {\n  Page&lt;DatCho&gt; findByNguoiIdOrderByBatDauDescIdDesc(Integer nguoiId, Pageable trang);\n\n  @Lock(LockModeType.PESSIMISTIC_WRITE)\n  @Query(\"select d from DatCho d where d.id = :id\")\n  Optional&lt;DatCho&gt; khoaDeSua(Integer id);\n\n  @Query(\"select count(d) from DatCho d where d.phong.id = :phongId and d.trangThai &lt;&gt; 'huy'\")\n  long demTheoPhong(Integer phongId);\n}";
export const CORS = "// cors.mjs — cho phép giao diện web (khác origin) gọi dat-api.\nconst ORIGIN = process.env.WEB_ORIGIN || 'http://localhost:41200';\n\nexport function cors(req, res) {\n  res.setHeader('Access-Control-Allow-Origin', ORIGIN);\n  res.setHeader('Vary', 'Origin');\n  if (req.method === 'OPTIONS') {\n    res.writeHead(204, {\n      'Access-Control-Allow-Methods': 'GET, POST',\n      'Access-Control-Allow-Headers': 'Content-Type',\n      'Access-Control-Max-Age': '600',\n    });\n    res.end();\n    return true;                       // đã trả lời preflight\n  }\n  return false;\n}";
export const BAO_CAO = "// bao-cao.mjs — báo cáo sử dụng phòng theo NGÀY (ngày theo giờ Việt Nam: người dùng và trường đều ở VN).\nimport { db } from './db.mjs';\n\nexport async function baoCaoNgay(ngay) {\n  if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(ngay || '')) return { code: 400, body: { loi: 'ngay phải có dạng YYYY-MM-DD' } };\n  const dau = new Date(ngay);\n  const { rows } = await db.query(\n    `SELECT d.id, d.phong_id, p.ten AS phong, d.bat_dau, d.ket_thuc FROM dat_cho d JOIN phong p ON p.id = d.phong_id\n      WHERE d.trang_thai &lt;&gt; 'huy' AND d.bat_dau &gt;= $1 AND d.bat_dau &lt; $2 ORDER BY d.bat_dau, d.id`,\n    [new Date(+dau - 864e5), new Date(+dau + 2 * 864e5)]);\n  const trongNgay = rows.filter((r) =&gt; r.bat_dau.toISOString().slice(0, 10) === ngay);\n  const theoPhong = {};\n  for (const r of trongNgay) theoPhong[r.phong] = (theoPhong[r.phong] || 0) + 1;\n  return { code: 200, body: { ngay, tong: trongNgay.length, theoPhong, ids: trongNgay.map((r) =&gt; r.id) } };\n}";
export const DAT_CHO = "// dat-cho.mjs — tạo lượt đặt phòng mới.\nimport { db } from './db.mjs';\nimport { hopLe, trungGio } from './khung-gio.mjs';\n\nexport async function datCho({ phongId, nguoiId, batDau, ketThuc }) {\n  const moi = { batDau: new Date(batDau), ketThuc: new Date(ketThuc) };\n  const loi = hopLe(moi);\n  if (loi) return { code: 400, body: { loi } };\n\n  // Lấy các lượt đặt của phòng trong ngày đó rồi kiểm trùng\n  const { rows } = await db.query(\n    `SELECT id, bat_dau, ket_thuc FROM dat_cho\n      WHERE phong_id = $1 AND trang_thai &lt;&gt; 'huy' AND bat_dau &lt; $3 AND ket_thuc &gt; $2`,\n    [phongId, new Date(+moi.batDau - 864e5), new Date(+moi.ketThuc + 864e5)]);\n  const dung = rows.find((r) =&gt; trungGio(moi, { batDau: r.bat_dau, ketThuc: r.ket_thuc }));\n  if (dung) return { code: 409, body: { loi: 'Phòng đã có người đặt khung giờ này', trungVoi: dung.id } };\n\n  const { rows: [r] } = await db.query(\n    'INSERT INTO dat_cho (phong_id, nguoi_id, bat_dau, ket_thuc) VALUES ($1, $2, $3, $4) RETURNING id',\n    [phongId, nguoiId, moi.batDau, moi.ketThuc]);\n  return { code: 201, body: { id: r.id } };\n}";
export const SU_KIEN = "// su-kien.mjs — đẩy sự kiện \"có lịch mới\" xuống trình duyệt bằng Server-Sent Events (GET /su-kien).\nconst ketNoi = new Set();\n\nexport function moSuKien(req, res) {\n  res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', Connection: 'keep-alive' });\n  res.write(': xin chào\\n\\n');\n  const nhip = setInterval(() =&gt; res.write(': ping\\n\\n'), 15000);   // giữ kết nối qua proxy\n  ketNoi.add({ res, nhip });\n}\n\nexport function phat(loai, duLieu) {\n  const goi = `event: ${loai}\\ndata: ${JSON.stringify(duLieu)}\\n\\n`;\n  for (const k of ketNoi) k.res.write(goi);\n}";
export const CACHE = "// cache.mjs — đệm danh sách phòng: lich-api (Java) là chủ dữ liệu phòng, dat-api chỉ đọc. Phòng ít khi đổi ⇒ giữ 10 phút.\nconst TTL_MS = 10 * 60 * 1000;\nconst kho = new Map();                   // khoá → { luc, giaTri }\n\nexport async function layHoacTai(khoa, tai) {\n  const o = kho.get(khoa);\n  if (o &amp;&amp; Date.now() - o.luc &lt; TTL_MS) return { giaTri: o.giaTri, trung: true, tuoi: Math.round((Date.now() - o.luc) / 1000) };\n  const giaTri = await tai();\n  kho.set(khoa, { luc: Date.now(), giaTri });\n  return { giaTri, trung: false, tuoi: 0 };\n}";
export const KHUNG_GIO = "// khung-gio.mjs — kiểm khung giờ đặt phòng. Dùng chung cho đặt chỗ mới và đổi giờ.\nconst PHUT = 60 * 1000;\n\n/** Khung giờ hợp lệ: bắt đầu trước kết thúc, dài 30 phút tới 4 giờ, rơi đúng mốc 15 phút. */\nexport function hopLe({ batDau, ketThuc }) {\n  if (!(batDau instanceof Date) || Number.isNaN(+batDau) || !(ketThuc instanceof Date) || Number.isNaN(+ketThuc)) return 'Giờ không hợp lệ';\n  const dai = (ketThuc - batDau) / PHUT;\n  if (dai &lt; 30 || dai &gt; 240) return 'Mỗi lượt đặt dài từ 30 phút tới 4 giờ';\n  if (batDau.getTime() % (15 * PHUT) !== 0) return 'Giờ bắt đầu phải rơi vào mốc 15 phút';\n  return null;\n}\n\n/** Hai khung giờ có giẫm lên nhau không. */\nexport const trungGio = (a, b) =&gt; a.batDau &lt;= b.ketThuc &amp;&amp; b.batDau &lt;= a.ketThuc;";
export const TEST_KG = "import { test } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { hopLe, trungGio } from '../src/khung-gio.mjs';\n\nconst k = (a, b) =&gt; ({ batDau: new Date(`2026-12-01T${a}:00+07:00`), ketThuc: new Date(`2026-12-01T${b}:00+07:00`) });\n\ntest('khung giờ hợp lệ', () =&gt; assert.equal(hopLe(k('09:00', '11:00')), null));\ntest('kết thúc trước bắt đầu bị từ chối', () =&gt; assert.match(hopLe(k('11:00', '09:00')), /30 phút/));\ntest('dài quá 4 giờ bị từ chối', () =&gt; assert.match(hopLe(k('07:00', '12:00')), /4 giờ/));\ntest('lệch mốc 15 phút bị từ chối', () =&gt; assert.match(hopLe(k('09:10', '10:10')), /15 phút/));\ntest('hai khung chồng nhau là trùng', () =&gt; assert.equal(trungGio(k('09:00', '11:00'), k('10:00', '12:00')), true));\ntest('khung nằm trong khung khác là trùng', () =&gt; assert.equal(trungGio(k('09:00', '12:00'), k('10:00', '11:00')), true));\ntest('hai khung cách nhau không trùng', () =&gt; assert.equal(trungGio(k('07:00', '08:00'), k('13:00', '15:00')), false));";
export const SUA_06 = "-- sua-06.sql — lỗi #1206 (đặt trùng khi bấm đồng thời): CSDL tự chặn hai lượt chồng giờ trong cùng phòng.\n-- tstzrange(bat_dau, ket_thuc) mặc định là '[)' ⇒ ca liền kề (11:00 kết thúc / 11:00 bắt đầu) vẫn hợp lệ.\nCREATE EXTENSION IF NOT EXISTS btree_gist;\nALTER TABLE dat_cho ADD CONSTRAINT dat_cho_khong_chong\n  EXCLUDE USING gist (phong_id WITH =, tstzrange(bat_dau, ket_thuc) WITH &amp;&amp;) WHERE (trang_thai &lt;&gt; 'huy');";
export const SUA_09 = "-- sua-09.sql — lỗi #1209 (tên phòng cũ sau khi đổi): mỗi khi bảng phong đổi, CSDL phát NOTIFY phong_doi; dat-api LISTEN và xoá đệm.\nCREATE OR REPLACE FUNCTION bao_phong_doi() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  PERFORM pg_notify('phong_doi', COALESCE(NEW.id, OLD.id)::text);\n  RETURN NULL;\nEND $$;\nCREATE TRIGGER phong_doi AFTER INSERT OR UPDATE OR DELETE ON phong FOR EACH ROW EXECUTE FUNCTION bao_phong_doi();";
export const DAT_CHO_SUA = "// dat-cho.mjs — tạo lượt đặt phòng mới.\nimport { db } from './db.mjs';\nimport { hopLe, trungGio } from './khung-gio.mjs';\n\nexport async function datCho({ phongId, nguoiId, batDau, ketThuc }) {\n  const moi = { batDau: new Date(batDau), ketThuc: new Date(ketThuc) };\n  const loi = hopLe(moi);\n  if (loi) return { code: 400, body: { loi } };\n\n  const c = await db.connect();\n  try {\n    await c.query('BEGIN');\n    // Xếp hàng theo PHÒNG: request thứ hai cho cùng phòng chờ ở đây tới khi request đầu COMMIT/ROLLBACK.\n    // Không có dòng này, 20 INSERT chồng nhau đụng ràng buộc EXCLUDE cùng lúc ⇒ PostgreSQL báo deadlock (40P01) ⇒ 500.\n    await c.query('SELECT pg_advisory_xact_lock(1206, $1)', [phongId]);\n    const { rows } = await c.query(\n      `SELECT id, bat_dau, ket_thuc FROM dat_cho\n        WHERE phong_id = $1 AND trang_thai &lt;&gt; 'huy' AND bat_dau &lt; $3 AND ket_thuc &gt; $2`,\n      [phongId, new Date(+moi.batDau - 864e5), new Date(+moi.ketThuc + 864e5)]);\n    const dung = rows.find((r) =&gt; trungGio(moi, { batDau: r.bat_dau, ketThuc: r.ket_thuc }));\n    if (dung) { await c.query('ROLLBACK'); return { code: 409, body: { loi: 'Phòng đã có người đặt khung giờ này', trungVoi: dung.id } }; }\n    const { rows: [r] } = await c.query(\n      'INSERT INTO dat_cho (phong_id, nguoi_id, bat_dau, ket_thuc) VALUES ($1, $2, $3, $4) RETURNING id',\n      [phongId, nguoiId, moi.batDau, moi.ketThuc]);\n    await c.query('COMMIT');\n    return { code: 201, body: { id: r.id } };\n  } catch (e) {\n    await c.query('ROLLBACK').catch(() =&gt; {});\n    // Lưới cuối: ràng buộc EXCLUDE (db/sua-06.sql) — bắt cả đường ghi không qua hàm này (lich-api, script nhập liệu…)\n    if (e.code === '23P01') return { code: 409, body: { loi: 'Phòng đã có người đặt khung giờ này' } };\n    throw e;\n  } finally { c.release(); }\n}";
export const DUA = "// dua.mjs — tái hiện lỗi #1206: N người bấm \"Đặt\" CÙNG LÚC cho cùng một phòng, cùng một khung giờ.\n//   node dua.mjs [số request=20] [http://127.0.0.1:41202]\nconst [n = 20, base = 'http://127.0.0.1:41202'] = process.argv.slice(2);\nconst than = { phongId: 22, nguoiId: 31, batDau: '2027-01-05T09:00:00+07:00', ketThuc: '2027-01-05T10:00:00+07:00' };\n// Làm nóng: mở sẵn kết nối HTTP và pool PostgreSQL như một máy chủ đã chạy lâu (thiếu bước này, các request tới lệch nhau vài ms ⇒ race khó lộ)\nawait Promise.all(Array.from({ length: +n }, (_, i) =&gt; fetch(i % 2 ? `${base}/health` : `${base}/bao-cao/ngay?ngay=2027-01-05`).then((r) =&gt; r.text())));\nconst kq = await Promise.all(Array.from({ length: +n }, () =&gt;\n  fetch(`${base}/dat-cho`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(than) })\n    .then(async (r) =&gt; `${r.status} ${await r.text()}`)));\nconst dem = {}; for (const k of kq) { const s = k.slice(0, 3); dem[s] = (dem[s] || 0) + 1; }\nconsole.log(kq.slice(0, 4).join('\\n') + (kq.length &gt; 4 ? '\\n…' : ''));\nconsole.log('đếm theo mã:', JSON.stringify(dem));";
export const LIEN_KE = "// lien-ke.test.mjs — test chặn tái phát lỗi #1210: hai lượt liền kề (lượt trước kết thúc đúng lúc lượt sau bắt đầu) KHÔNG trùng.\nimport { test } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { trungGio } from '../src/khung-gio.mjs';\n\nconst k = (a, b) =&gt; ({ batDau: new Date(`2026-12-01T${a}:00+07:00`), ketThuc: new Date(`2026-12-01T${b}:00+07:00`) });\n\ntest('10:00–11:00 và 11:00–12:00 không trùng (liền kề)', () =&gt; assert.equal(trungGio(k('10:00', '11:00'), k('11:00', '12:00')), false));\ntest('đảo thứ tự cũng không trùng', () =&gt; assert.equal(trungGio(k('11:00', '12:00'), k('10:00', '11:00')), false));\ntest('chồng 1 phút thì trùng', () =&gt; assert.equal(trungGio(k('10:00', '11:01'), k('11:00', '12:00')), true));";
export const BISECT = "#!/bin/bash\n# bisect-kiem.sh — git bisect run gọi script này ở MỖI commit. 0 = tốt, 1 = xấu, 125 = không kiểm được (bỏ qua commit).\n# Test nằm NGOÀI repo (chép tạm vào khi chạy) để mọi commit cũ đều dùng chung một phép kiểm.\ncp \"$(dirname \"$0\")/lien-ke.test.mjs\" test/zz-lien-ke.test.mjs\nnode -e \"import('./src/khung-gio.mjs')\" 2&gt;/dev/null || { rm -f test/zz-lien-ke.test.mjs; exit 125; }   # mã không nạp được ⇒ bỏ qua\nnode --test test/zz-lien-ke.test.mjs &gt; /dev/null 2&gt;&amp;1; kq=$?\nrm -f test/zz-lien-ke.test.mjs\nexit $kq";
export const TAO_LS = "#!/bin/bash\n# tao-lich-su.sh &lt;thư mục đích&gt; — dựng repo git của dat-api (dịch vụ Node) với lịch sử 40 commit, từ v1.0.0 tới v1.6.0.\n# Cây ở HEAD = đúng mã nguồn trong cap/node (cộng CHANGELOG.md, docs/ do script sinh). Tác giả + ngày cố định ⇒ hash giống nhau mỗi lần dựng.\n# Lỗi số 10 (hồi quy \"không đặt được ca liền kề\") nằm ở MỘT commit trong lịch sử — người học tìm bằng git bisect run.\nset -euo pipefail\nNGUON=\"$(cd \"$(dirname \"$0\")/../cap/node\" &amp;&amp; pwd)\"\nDICH=\"$1\"\nrm -rf \"$DICH\"; mkdir -p \"$DICH\"; cd \"$DICH\"\ngit init -q -b main\ngit config user.name \"LabFlow CI\"; git config user.email \"ci@labflow.test\"; git config commit.gpgsign false\n\ncp -r \"$NGUON/src\" \"$NGUON/test\" \"$NGUON/package.json\" .\nprintf 'node_modules/\\n*.log\\n' &gt; .gitignore\nmkdir -p docs\nKG=src/khung-gio.mjs\nTOT='export const trungGio = (a, b) =&gt; a.batDau &lt; b.ketThuc \\&amp;\\&amp; b.batDau &lt; a.ketThuc;'\nXAU='export const trungGio = (a, b) =&gt; a.batDau &lt;= b.ketThuc \\&amp;\\&amp; b.batDau &lt;= a.ketThuc;'\nsed -i \"s/^export const trungGio = .*/$TOT/\" $KG\ncp $KG /tmp/kg-tot.$$\n: &gt; CHANGELOG.md\n\nN=0\ncm() {   # cm &lt;tác giả&gt; &lt;thông điệp&gt;\n  N=$((N + 1))\n  local ngay; ngay=$(date -u -d \"2026-10-01 09:00 +07:00 + $((N * 30)) hours\" '+%Y-%m-%dT%H:%M:%S+07:00')\n  local ten=\"${1%% &lt;*}\" mail; mail=\"${1##*&lt;}\"; mail=\"${mail%&gt;}\"\n  git add -A\n  GIT_AUTHOR_NAME=\"$ten\" GIT_AUTHOR_EMAIL=\"$mail\" GIT_AUTHOR_DATE=\"$ngay\" \\\n  GIT_COMMITTER_NAME=\"$ten\" GIT_COMMITTER_EMAIL=\"$mail\" GIT_COMMITTER_DATE=\"$ngay\" git commit -q -m \"$2\"\n}\nphienBan() {  # phienBan 1.2.0 — đổi version ở package.json và app.mjs\n  sed -i \"s/\\\"version\\\": \\\"[0-9.]*\\\"/\\\"version\\\": \\\"$1\\\"/\" package.json\n  sed -i \"s/^const PHIEN_BAN = '[0-9.]*';/const PHIEN_BAN = '$1';/\" src/app.mjs\n  printf '\\n## %s\\n' \"$1\" &gt;&gt; CHANGELOG.md\n}\nghi() { printf -- '- %s\\n' \"$2\" &gt;&gt; CHANGELOG.md; cm \"$1\" \"$2\"; }\nAN=\"An Nguyễn &lt;an@labflow.test&gt;\"; BINH=\"Bình Trần &lt;binh@labflow.test&gt;\"; CHI=\"Chi Lê &lt;chi@labflow.test&gt;\"; DUNG=\"Dũng Phạm &lt;dung@labflow.test&gt;\"\n\nphienBan 1.0.0; ghi \"$AN\" \"khởi tạo dat-api: đặt chỗ, báo cáo ngày\"\necho '# dat-api' &gt; README.md; ghi \"$AN\" \"docs: README\"\necho 'Chạy: npm start (cần PostgreSQL 16)' &gt;&gt; README.md; ghi \"$BINH\" \"docs: cách chạy\"\nprintf '# Kiến trúc\\n\\nweb → dat-api (Node) và lich-api (Spring Boot), chung PostgreSQL.\\n' &gt; docs/kien-truc.md; ghi \"$AN\" \"docs: sơ đồ kiến trúc\"\nphienBan 1.1.0; ghi \"$BINH\" \"feat: GET /phong đệm từ lich-api\"\nprintf '\\n## API\\n- POST /dat-cho\\n- GET /bao-cao/ngay\\n' &gt;&gt; README.md; ghi \"$CHI\" \"docs: liệt kê API\"\nprintf '# Quy ước commit\\n\\nfeat/fix/docs/refactor/test/chore\\n' &gt; docs/quy-uoc.md; ghi \"$AN\" \"docs: quy ước commit\"\nprintf '\\n- GET /phong, /phong/:id\\n' &gt;&gt; README.md; ghi \"$BINH\" \"docs: API phòng\"\nphienBan 1.2.0; ghi \"$CHI\" \"feat: X-Request-Id trong log\"\nprintf '\\n## Log\\nMỗi dòng log là JSON có rid.\\n' &gt;&gt; docs/kien-truc.md; ghi \"$CHI\" \"docs: định dạng log\"\nprintf '# Vận hành\\n\\n- /health trả phienBan + commit\\n' &gt; docs/van-hanh.md; ghi \"$DUNG\" \"docs: sổ vận hành\"\nprintf -- '- Cổng 41202\\n' &gt;&gt; docs/van-hanh.md; ghi \"$DUNG\" \"docs: cổng dịch vụ\"\nphienBan 1.3.0; ghi \"$BINH\" \"feat: GET /su-kien (SSE) báo lịch mới\"\nprintf -- '- SSE: proxy phải tắt đệm\\n' &gt;&gt; docs/van-hanh.md; ghi \"$DUNG\" \"docs: lưu ý SSE sau proxy\"\nprintf '\\nTest: npm test\\n' &gt;&gt; README.md; ghi \"$AN\" \"docs: cách chạy test\"\nprintf -- '- Cảnh báo: p99 &gt; 500 ms\\n' &gt;&gt; docs/van-hanh.md; ghi \"$DUNG\" \"docs: ngưỡng cảnh báo\"\nprintf '\\n## Đặt chỗ\\nKhung giờ dài 30 phút – 4 giờ, mốc 15 phút; hai lượt liền kề (11:00 kết thúc, 11:00 bắt đầu) được phép.\\n' &gt;&gt; docs/kien-truc.md; ghi \"$CHI\" \"docs: luật khung giờ\"\nphienBan 1.4.0; ghi \"$AN\" \"chore: phát hành 1.4.0\"; git tag v1.4.0\nprintf -- '- Sao lưu DB mỗi đêm 02:00\\n' &gt;&gt; docs/van-hanh.md; ghi \"$DUNG\" \"docs: lịch sao lưu\"\nprintf '\\n## Báo cáo\\nNgày tính theo giờ Việt Nam.\\n' &gt;&gt; docs/kien-truc.md; ghi \"$CHI\" \"docs: báo cáo theo ngày\"\nprintf -- '- Khởi động lại: systemctl restart dat-api\\n' &gt;&gt; docs/van-hanh.md; ghi \"$DUNG\" \"docs: khởi động lại dịch vụ\"\nprintf '\\n## Đóng góp\\nMở PR nhỏ, có mô tả vì sao.\\n' &gt;&gt; README.md; ghi \"$AN\" \"docs: hướng dẫn đóng góp\"\nphienBan 1.5.0; ghi \"$BINH\" \"chore: phát hành 1.5.0\"; git tag v1.5.0\nprintf -- '- Log giữ 14 ngày\\n' &gt;&gt; docs/van-hanh.md; ghi \"$DUNG\" \"docs: thời gian giữ log\"\nprintf '\\n## Đổi giờ\\nlich-api (Java) xử lý đổi giờ giữa hai lượt.\\n' &gt;&gt; docs/kien-truc.md; ghi \"$CHI\" \"docs: đổi giờ ở lich-api\"\nsed -i 's|^  if (batDau.getTime() % (15 \\* PHUT) !== 0) return|  if (batDau.getTime() % (15 * PHUT) !== 0 {  return|' $KG; ghi \"$BINH\" \"wip: tách kiểm mốc 15 phút\"\nprintf -- '- (đang viết)\\n' &gt;&gt; docs/van-hanh.md; ghi \"$BINH\" \"wip: viết tiếp phần kiểm khung giờ\"\nprintf -- '- Hai lượt liền kề được phép\\n' &gt;&gt; docs/van-hanh.md; ghi \"$DUNG\" \"docs: ghi chú cho đội hỗ trợ\"\ncp /tmp/kg-tot.$$ $KG; ghi \"$BINH\" \"fix: lỗi cú pháp ở khung-gio\"\nsed -i \"s/^export const trungGio = .*/$XAU/\" $KG; ghi \"$BINH\" \"refactor(khung-gio): dùng chung trungGio cho đặt chỗ và đổi giờ, tính cả trường hợp chạm biên\"\nprintf -- '- Tài khoản bộ kiểm: kiem@labflow.test\\n' &gt;&gt; docs/van-hanh.md; ghi \"$DUNG\" \"docs: tài khoản bộ kiểm\"\nprintf '\\n## Bộ đệm\\n/phong giữ 10 phút (phòng ít khi đổi).\\n' &gt;&gt; docs/kien-truc.md; ghi \"$BINH\" \"docs: thời gian đệm phòng\"\nprintf -- '- Bảng điều khiển: Grafana &gt; LabFlow\\n' &gt;&gt; docs/van-hanh.md; ghi \"$DUNG\" \"docs: nơi xem số đo\"\nprintf '\\nGiấy phép: nội bộ.\\n' &gt;&gt; README.md; ghi \"$AN\" \"docs: giấy phép\"\nprintf -- '- Liên hệ trực: #labflow-oncall\\n' &gt;&gt; docs/van-hanh.md; ghi \"$DUNG\" \"docs: kênh trực\"\nprintf '\\n## Phụ thuộc\\npg 8.x\\n' &gt;&gt; docs/kien-truc.md; ghi \"$CHI\" \"docs: phụ thuộc\"\nprintf -- '- Ghi chú phát hành ở CHANGELOG.md\\n' &gt;&gt; README.md; ghi \"$AN\" \"docs: trỏ tới CHANGELOG\"\nphienBan 1.6.0; ghi \"$AN\" \"chore: phát hành 1.6.0\"; git tag v1.6.0\nrm -f /tmp/kg-tot.$$\n# Kiểm: cây ở HEAD khớp mã nguồn\nfor f in $(cd \"$NGUON\" &amp;&amp; find src test package.json -type f); do cmp -s \"$f\" \"$NGUON/$f\" || { echo \"LỆCH $f\" &gt;&amp;2; exit 1; }; done\necho \"repo $DICH: $(git rev-list --count HEAD) commit, HEAD $(git rev-parse --short HEAD), tag: $(git tag | tr '\\n' ' ')\"";
export const TRINH_DUYET = "// trinh-duyet.mjs — lái Chrome headless qua CDP như một người dùng: mở trang, bấm tab, điền form; in Console + lỗi mạng (CORS) + chụp ảnh.\n//   node trinh-duyet.mjs &lt;url&gt; '&lt;các bước JSON&gt;' [ảnh.png]\n//   bước: {\"tab\":\"Đặt phòng\"} | {\"bam\":\"button\"} | {\"cho\":ms} | {\"doc\":\"#thong-bao\"} | {\"eval\":\"js\"}\nimport { spawn } from 'node:child_process'; import fs from 'node:fs';\nconst [url, buocJson = '[]', anh] = process.argv.slice(2);\nconst CONG = 49260 + Math.floor(Math.random() * 30);\nconst dir = fs.mkdtempSync('/tmp/dbg-lab/chrome-');\nconst chrome = spawn('google-chrome', ['--headless=new', `--remote-debugging-port=${CONG}`, `--user-data-dir=${dir}`, '--no-first-run', '--window-size=1100,800', 'about:blank'], { stdio: 'ignore' });\nlet t; for (let i = 0; i &lt; 50; i++) { try { t = (await (await fetch(`http://127.0.0.1:${CONG}/json/list`)).json()).find((x) =&gt; x.type === 'page'); if (t) break; } catch {} await new Promise((r) =&gt; setTimeout(r, 200)); }\nconst ws = new WebSocket(t.webSocketDebuggerUrl); await new Promise((r) =&gt; ws.addEventListener('open', r));\nlet id = 0; const pend = new Map(); const req = new Map();\nconst ngan = (s) =&gt; s.replace(/[0-9a-f]{8}-[0-9a-f-]{27}/g, '&lt;uuid&gt;');\nws.addEventListener('message', (e) =&gt; {\n  const m = JSON.parse(e.data); if (m.id) return pend.get(m.id)?.(m);\n  const p = m.params;\n  if (m.method === 'Runtime.consoleAPICalled') { const s = p.args.map((a) =&gt; a.value ?? a.description).join(' '); if (!/vite|React DevTools|HMR/.test(s)) console.log(`[console.${p.type}] ${s}`); }\n  if (m.method === 'Runtime.exceptionThrown') console.log(`[uncaught] ${p.exceptionDetails.exception?.description?.split('\\n')[0]}`);\n  if (m.method === 'Log.entryAdded' &amp;&amp; !/favicon/.test(p.entry.url || '')) console.log(`[${p.entry.source}/${p.entry.level}] ${ngan(p.entry.text)}`);\n  if (m.method === 'Network.requestWillBeSent') req.set(p.requestId, `${p.request.method} ${p.request.url}`);\n  if (m.method === 'Network.responseReceived' &amp;&amp; /127\\.0\\.0\\.1:412/.test(p.response.url) &amp;&amp; p.type !== 'EventSource') console.log(`[network] ${req.get(p.requestId)} → ${p.response.status}`);\n  if (m.method === 'Network.loadingFailed' &amp;&amp; req.get(p.requestId)) console.log(`[network] ${req.get(p.requestId)} → FAILED ${p.errorText}${p.corsErrorStatus ? ' cors=' + p.corsErrorStatus.corsError : ''}`);\n});\nconst send = (method, params = {}) =&gt; new Promise((r) =&gt; { const i = ++id; pend.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });\nconst ev = async (expression) =&gt; (await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })).result.result?.value;\nawait send('Runtime.enable'); await send('Log.enable'); await send('Network.enable'); await send('Page.enable');\nawait send('Page.navigate', { url }); await new Promise((r) =&gt; setTimeout(r, 2500));\nfor (const b of JSON.parse(buocJson)) {\n  if (b.tab) await ev(`[...document.querySelectorAll('nav button')].find(x =&gt; x.textContent === ${JSON.stringify(b.tab)}).click()`);\n  if (b.bam) await ev(`document.querySelector(${JSON.stringify(b.bam)}).click()`);\n  if (b.eval) console.log(`[eval] ${await ev(b.eval)}`);\n  if (b.doc) console.log(`[màn hình] ${b.doc}: ${await ev(`document.querySelector(${JSON.stringify(b.doc)})?.innerText`)}`);\n  await new Promise((r) =&gt; setTimeout(r, b.cho ?? 1200));\n}\nif (anh) fs.writeFileSync(anh, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'));\nws.close(); chrome.kill(); await new Promise((r) =&gt; setTimeout(r, 300)); fs.rmSync(dir, { recursive: true, force: true });";
export const TAI_SSE = "// tai-sse.mjs &lt;số kết nối&gt; &lt;url&gt; — mở rồi đóng N kết nối Server-Sent Events, như N lần người dùng đổi tab/tải lại trang.\nimport http from 'node:http';\nconst [n, url] = process.argv.slice(2);\nfor (let i = 0; i &lt; +n; i += 50) await Promise.all(Array.from({ length: Math.min(50, n - i) }, () =&gt; new Promise((xong) =&gt; {\n  const rq = http.get(url, (res) =&gt; res.once('data', () =&gt; { rq.destroy(); xong(); })); rq.on('error', xong);\n})));\nconsole.log(`đã mở và đóng ${n} kết nối ${url}`);";
export const HEAP = "// heap.mjs — chụp heap snapshot qua inspector (đúng lệnh DevTools gửi: HeapProfiler.takeHeapSnapshot) và phân tích như tab Memory.\n//   node heap.mjs chup &lt;cổng inspector&gt; &lt;tệp.heapsnapshot&gt;\n//   node heap.mjs so &lt;cũ&gt; &lt;mới&gt;               — bảng \"Comparison\": lớp nào tăng nhiều nhất\n//   node heap.mjs giu &lt;tệp&gt; &lt;TênLớp&gt;          — đường \"Retainers\": ai đang giữ một đối tượng của lớp đó\nimport fs from 'node:fs';\nconst [lenh, a, b, c] = process.argv.slice(2);\n\nif (lenh === 'chup') {\n  const ds = await (await fetch(`http://127.0.0.1:${a}/json/list`)).json();\n  const ws = new WebSocket(ds[0].webSocketDebuggerUrl);\n  await new Promise((r) =&gt; (ws.onopen = r));\n  const out = fs.createWriteStream(b); let id = 0;\n  const gui = (method, params = {}) =&gt; new Promise((r) =&gt; { const my = ++id; ws.addEventListener('message', function f(e) { const m = JSON.parse(e.data); if (m.id === my) { ws.removeEventListener('message', f); r(m); } }); ws.send(JSON.stringify({ id: my, method, params })); });\n  ws.addEventListener('message', (e) =&gt; { const m = JSON.parse(e.data); if (m.method === 'HeapProfiler.addHeapSnapshotChunk') out.write(m.params.chunk); });\n  await gui('HeapProfiler.enable');\n  await gui('HeapProfiler.takeHeapSnapshot', { reportProgress: false });   // V8 chạy GC đầy đủ trước khi chụp\n  await new Promise((r) =&gt; out.end(r)); ws.close();\n  console.log(`đã chụp ${b} (${(fs.statSync(b).size / 2 ** 20).toFixed(1)} MB)`);\n  process.exit(0);\n}\n\nfunction doc(tep) {\n  const s = JSON.parse(fs.readFileSync(tep, 'utf8'));\n  const m = s.snapshot.meta, nf = m.node_fields.length, ef = m.edge_fields.length;\n  const T = m.node_types[0], ET = m.edge_types[0];\n  const iT = m.node_fields.indexOf('type'), iN = m.node_fields.indexOf('name'), iS = m.node_fields.indexOf('self_size'), iE = m.node_fields.indexOf('edge_count'), iId = m.node_fields.indexOf('id');\n  const N = s.nodes, E = s.edges, S = s.strings, n = N.length / nf;\n  const ten = (k) =&gt; { const t = T[N[k * nf + iT]]; const nm = S[N[k * nf + iN]]; return t === 'object' || t === 'closure' ? (t === 'closure' ? `(closure) ${nm}` : nm) : `(${t})`; };\n  return { s, N, E, S, n, nf, ef, T, ET, iT, iN, iS, iE, iId, ten };\n}\nfunction tomTat(h) {\n  const m = new Map();\n  for (let k = 0; k &lt; h.n; k++) { const t = h.ten(k); const v = m.get(t) || { so: 0, kt: 0 }; v.so++; v.kt += h.N[k * h.nf + h.iS]; m.set(t, v); }\n  return m;\n}\nconst kb = (x) =&gt; (x / 1024).toFixed(0).padStart(8) + ' KB';\n\nif (lenh === 'so') {\n  const A = tomTat(doc(a)), B = tomTat(doc(b));\n  const dong = [...B].map(([t, v]) =&gt; ({ t, them: v.so - (A.get(t)?.so || 0), kt: v.kt - (A.get(t)?.kt || 0) })).sort((x, y) =&gt; y.kt - x.kt).slice(0, 8);\n  console.log('Constructor'.padEnd(34) + '# Delta'.padStart(10) + 'Size Delta'.padStart(14));\n  for (const d of dong) console.log(d.t.slice(0, 33).padEnd(34) + ('+' + d.them).padStart(10) + ('+' + kb(d.kt).trim()).padStart(14));\n  if (c) { console.log('…'); for (const t of c.split(',')) { const v = B.get(t) || { so: 0, kt: 0 }, u = A.get(t) || { so: 0, kt: 0 }; console.log(t.slice(0, 33).padEnd(34) + ('+' + (v.so - u.so)).padStart(10) + ('+' + kb(v.kt - u.kt).trim()).padStart(14)); } }\n}\n\nif (lenh === 'giu') {\n  const h = doc(a);\n  const firstEdge = new Uint32Array(h.n + 1);\n  for (let k = 0; k &lt; h.n; k++) firstEdge[k + 1] = firstEdge[k] + h.N[k * h.nf + h.iE];\n  const iTo = h.s.snapshot.meta.edge_fields.indexOf('to_node'), iEt = h.s.snapshot.meta.edge_fields.indexOf('type'), iEn = h.s.snapshot.meta.edge_fields.indexOf('name_or_index');\n  const cha = Array.from({ length: h.n }, () =&gt; []);\n  for (let k = 0; k &lt; h.n; k++) for (let e = firstEdge[k]; e &lt; firstEdge[k + 1]; e++) {\n    const to = h.E[e * h.ef + iTo] / h.nf, et = h.ET[h.E[e * h.ef + iEt]];\n    if (et === 'weak' || et === 'shortcut') continue;\n    const nm = et === 'element' || et === 'hidden' ? `[${h.E[e * h.ef + iEn]}]` : h.S[h.E[e * h.ef + iEn]];\n    cha[to].push({ tu: k, nm });\n  }\n  // BFS ngược từ gốc (node 0 = (GC roots) tổng hợp) xuống: tìm đường ngắn nhất tới một đối tượng của lớp c... dùng BFS xuôi từ gốc\n  const truoc = new Int32Array(h.n).fill(-1), canh = new Array(h.n); const q = [0]; truoc[0] = 0;\n  const con = Array.from({ length: h.n }, () =&gt; []);\n  for (let to = 0; to &lt; h.n; to++) for (const p of cha[to]) con[p.tu].push({ to, nm: p.nm });\n  let dich = -1;\n  while (q.length &amp;&amp; dich &lt; 0) { const k = q.shift(); for (const x of con[k]) if (truoc[x.to] &lt; 0) { truoc[x.to] = k; canh[x.to] = x.nm; if (h.ten(x.to) === b) { dich = x.to; break; } q.push(x.to); } }\n  const duong = []; for (let k = dich; k !== 0; k = truoc[k]) duong.push(`${h.ten(k)} @${h.N[k * h.nf + h.iId]}` + (canh[k] !== undefined ? `  ← .${canh[k]} của` : ''));\n  console.log(`Retainers của một ${b} (đọc từ trên xuống: đối tượng ← ai giữ nó):`);\n  duong.forEach((d, i) =&gt; console.log('  '.repeat(i) + d));\n  console.log('  '.repeat(duong.length) + '(GC roots)');\n}";
